def evaluate_route(instance, route):
    states = propagate_route(instance, route)
    if any(state.battery_arrival < 0 for state in states):
        return float('inf'), float('inf')  # Not feasible
    total_distance = sum(distance(instance.node_map[route[i]], instance.node_map[route[i + 1]]) for i in range(len(route) - 1))
    return len(route), total_distance

