def repair_battery_feasibility(instance, route):
    states = propagate_route(instance, route)
    for state in states:
        if state.battery_arrival < 0:
            # Insert a charging station before the first infeasible stop
            for station_id in instance.station_ids:
                new_route = route[:route.index(state.node_id)] + [station_id, state.node_id] + route[route.index(state.node_id):]
                new_states = propagate_route(instance, new_route)
                if all(state.battery_arrival >= 0 for state in new_states):
                    return new_route
    return route

